const api=window.desktopAPI,$=s=>document.querySelector(s);
function update(s){$('#mini-status').textContent=s.status;$('#mini-eval').textContent=s.evaluation;$('#mini-move').textContent=s.move;$('#mini-guide').hidden=!s.instruction;$('#mini-from').textContent=s.fromText||'';$('#mini-to').textContent=s.toText||'';$('#mini-instruction').textContent=s.instruction||'';$('#mini-coordinates').textContent=[s.coordinateNote,s.arrowNote].filter(Boolean).join(' · ');$('#mini-hint').textContent=s.hint||'点击“重新读取”选择浏览器或显示器';$('#mini-detail').textContent=s.detail||'';document.body.dataset.level=s.level;$('#mini-pause').disabled=!['跟踪中','已暂停','待重新确认','等候棋盘','切回棋局'].includes(s.status);$('#mini-pause').textContent=['跟踪中','等候棋盘','切回棋局'].includes(s.status)?'暂停':'继续看棋';$('#mini-stop').disabled=s.status.includes('未开始');}
function lock(value){$('#mini-lock').checked=value;document.body.dataset.locked=value;$('#mini-lock-note').textContent=value?'已穿透 · Ctrl / ⌘ + Shift + O 解锁':'拖动顶部可移动 · Ctrl / ⌘ + Shift + O 解锁';}
api.onSummary(update);api.onOverlayLock(lock);update(await api.getSummary());lock(await api.getOverlayLock());$('#mini-show').onclick=()=>api.showMain();$('#mini-pause').onclick=()=>api.pause();$('#mini-restart').onclick=()=>api.restart();$('#mini-stop').onclick=()=>api.stop();$('#mini-lock').onchange=()=>api.setOverlayLock($('#mini-lock').checked);
